+@inject PersistentComponentState ApplicationState
+
+<PageTitle>Inventory</PageTitle>
+
+<h1>Equipment Inventory</h1>
+
+@if (_items is null)
+{
+    <p><em>Loading inventory...</em></p>
+}
+else
+{
+    <table class="table">
+        <thead>
+            <tr>
+                <th>Id</th>
+                <th>Name</th>
+                <th>Location</th>
+                <th>Last Inspected</th>
+            </tr>
+        </thead>
+        <tbody>
+            @foreach (var item in _items)
+            {
+                <tr>
+                    <td>@item.Id</td>
+                    <td>@item.Name</td>
+                    <td>@item.Location</td>
+                    <td>@item.LastInspected.ToShortDateString()</td>
+                </tr>
+            }
+        </tbody>
+    </table>
+}
+
+@code {
+    private List<EquipmentItem>? _items;
+    private PersistingComponentStateSubscription _persistSubscription;
+
+    protected override async Task OnInitializedAsync()
+    {
+        // During interactive activation, try to restore persisted data first.
+        // This avoids a second call to the service after the SignalR circuit starts.
+        _persistSubscription = ApplicationState.RegisterOnPersisting(PersistData);
+
+        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
+        {
+            _items = restored;
+        }
+        else
+        {
+            _items = await EquipmentSvc.GetEquipmentAsync();
+        }
+    }
+
+    private Task PersistData()
+    {
+        ApplicationState.PersistAsJson("equipment", _items);
+        return Task.CompletedTask;
+    }
+
+    public void Dispose()
+    {
+        _persistSubscription.Dispose();
+    }
+}
+

